import { BaseComponent } from "../../utils/baseElement";
import styles from "./Cell.module.scss";

class Cell extends BaseComponent {
  constructor() {
    super({ tag: "button", className: styles.cell });
    this.addAttributes({ "aria-label": "cell" });
    this.getNode();
  }

  onRightClick(cb) {
    this.addListener("contextmenu", (event) => {
      event.preventDefault();
      this.setMark();
      cb(event);
    });
  }

  onLeftClick(cb) {
    this.addListener("click", (event) => {
      cb(event);
      this.setBackground();
    });
  }

  setBackground() {
    this.removeClass(styles.marked);
    if (!this.getNode().classList.contains((styles.filled))) {
      this.addClass(styles.filled);
    } else {
      this.removeClass(styles.filled);
    }
  }

  setMark() {
    this.removeClass(styles.filled);
    if (!this.getNode().classList.contains((styles.marked))) {
      this.addClass(styles.marked);
    } else {
      this.removeClass(styles.marked);
    }
  }

  disable() {
    this.getNode().disabled = true;
  }

  enable() {
    this.getNode().disabled = false;
  }
}
export { Cell }; //gameboard
