import { GameControls } from "../Controls/GameControls";
import { BaseComponent } from "../../utils/baseElement";
import { GameBoard } from "../GameBoard/GameBoard";
import styles from "./Main.module.scss";
import { stateMachine } from "../../core/StateMachine";
import { ControlButtonsController } from "../Controls/ControlButtonsController";
import { TemplateSelector } from "../Controls/TemplateSelector";
import { levelConfig } from "../../core/levelConfig";
import { TemplateController } from "../Controls/TemplateController";
import { CellController } from "../Cell/CellController";
import { Modal } from "../Modal/Modal";
import { AudioController } from "../Audio/AudioController";
import { LeaderBoard } from "../LeaderBoard/LeaderBoard";

class Main extends BaseComponent {
  /**
   *
   * @param {string} tag
   * @param {string} className
   */
  constructor() {
    super({ tag: "main", className: styles.main });

    this.getNode();
    this.subscribeToState();

    this.addInvitation();
    this.addTemplateSelector();
    this.addControls();

    this.audioController = new AudioController(stateMachine);

    this.controlButtonsController = new ControlButtonsController(
      stateMachine,
      this.controls,
      levelConfig,
    );

    this.templateController = new TemplateController(
      levelConfig,
      stateMachine,
      this.templateSelector,
    );

    this.cellController = new CellController(stateMachine);

    this.addGameBoard();
    this.addLeaderBoard();
  }

  addLeaderBoard() {
    this.leaderBoard = new LeaderBoard();
    this.append(this.leaderBoard);
  }
  addInvitation() {
    this.h2 = new BaseComponent({
      tag: "h2",
      className: styles.invitation,
      text: "Hi! Do you wanna choose a game? ",
    });
    this.append(this.h2);
  }

  addTemplateSelector() {
    this.templateSelector = new TemplateSelector(levelConfig);
    this.append(this.templateSelector);
  }

  addControls() {
    this.controls = new GameControls();
    this.append(this.controls);
  }

  addGameBoard() {
    this.gameBoard = new GameBoard(
      this.templateController,
      this.cellController,
      stateMachine,
    );
    this.append(this.gameBoard);
  }

  addModal(text) {
    // TODO костыль :/
    if (this.modal) {
      this.modal.destroy();
    }
    this.modal = new Modal({
      text: text,
      onClose: () => this.modal.getNode().close(),
    });
    document.body.appendChild(this.modal.getNode());
    return this.modal.getNode().showModal();
  }

  subscribeToState() {
    stateMachine.subscribe("stateChanged", ({ state }) => {
      if (state === "stateGameOver") {
        this.addModal(stateMachine.getContext().message);
        // this.leaderBoard.addResults();
      }
    });
  }
}

export { Main }; //wrapper
