import { BaseComponent } from "../../utils/baseElement";
import styles from "./Timer.module.scss";

class Timer extends BaseComponent {
  constructor(stateMachine) {
    super({ tag: "span", className: styles.timer });
    this.stateMachine = stateMachine;
    this.timer = null;
    this.startTime = null;
    this.gameTime = 0;
    this.isRunninig = false;

    this.stateMachine.subscribe(
      "stateChanged",
      ({ trigger, state, context: { updateContext } }) => {
        if (trigger === "win") {
          updateContext({
            message: `Great! You have solved the nonogram in ${this.timerTime} seconds!`,
          });

          this.resetTimer();
        }

        if (
          trigger === "cellClick" ||
          (trigger === "cellClickRight" && !this.isRunninig)
        ) {
          this.startTimer();
        }

        if (state !== "statePlaying") {
          this.resetTimer();
        }

        if (trigger === "saveGame") {
          this.pauseTimer();
        }

        // if (trigger === "continue") {
        //   this.setTextContent(getContext().time); // TODO не уверена что работает
        //   this.startTime();
        // }
      },
    );
    this.updateDisplay();
  }

  resetTimer() {
    if (this.timer) {
      clearInterval(this.timer);
      this.startTime = null;
      this.timer = null;
      this.gameTime = 0;
      this.updateDisplay();
      this.isRunninig = false;
    }
  }

  startTimer() {
    if (this.isRunninig) {
      return;
    }
    this.isRunninig = true;
    this.startTime = Date.now() - this.gameTime * 1000;
    this.timer = setInterval(() => {
      this.gameTime = Math.floor((Date.now() - this.startTime) / 1000);
      this.updateDisplay();
    }, 1000);
  }

  pauseTimer() {
    if (!this.isRunninig) return;
    clearInterval(this.timer);
    this.isRunninig = false;
  }

  getMins() {
    return Math.floor(this.gameTime / 60);
  }

  getSecs() {
    return this.gameTime % 60;
  }
  updateDisplay() {
    const resultMin = String(this.getMins()).padStart(2, "0");
    const resultSec = String(this.getSecs()).padStart(2, "0");
    this.timerTime = `Time: ${resultMin}:${resultSec}`;
    this.setTextContent(this.timerTime);
  }
}

export { Timer }; //header
