import { BaseComponent } from "../../utils/baseElement";
import { Timer } from "../Timer/Timer";
import styles from "./Header.module.scss";

class Header extends BaseComponent {
  /**
   *
   * @param {string} tag
   * @param {string} className
   */
  constructor(stateMachine) {
    super({ tag: "header", className: styles.header });
    this.stateMachine = stateMachine;
    this.getNode();
    this.addLogo();
    this.addTimer();
    this.addH1();
  }

  addH1() {
    const h1 = new BaseComponent({
      tag: "h1",
      className: styles.h1,
      text: "Nonograms",
    });
    this.append(h1);
  }

  addLogo() {
    const a = new BaseComponent({
      tag: "a",
      className: styles.logoLink,
    });

    a.addAttributes({
      href: "./",
    });

    const logo = new BaseComponent({
      tag: "img",
    });

    logo.addAttributes({
      src: "/img/favicon.ico",
      alt: "Logo Nonograms",
    });

    a.append(logo);
    this.append(a);
  }

  addTimer() {
    const timer = new Timer(this.stateMachine);
    this.append(timer);
  }
}

export { Header }; //wrapper
