import { createMachine } from "../utils/createStateMachine2";
import { levelConfig } from "./levelConfig";
import { cellClickAction, cellClickRightAction } from "./cellClickAction.js";
import { getDataFromLS } from "./useLocalStorage";

/**
 * @typedef {Object} StateDef
 * @property {Object} actions - object of actions for the state
 * @property {Object} transitions - object of transitions for the state
 * @property {Function} [actions.onEnter] - action for entering in the state
 * @property {Function} [actions.onExit] - action for leaving the state
 * @property {Object} [transitions.switch] - transition for the switch event
 * @property {Function} [transitions.switch.actions] - target state of transition
 * @property {string} [transitions.switch.target] - action while transiting
 */

const initialTemplate = levelConfig.easy.find(
  (template) => template.name === "Dog",
);

const stateMachine = createMachine({
  initialState: "stateWaitingForInput",
  context: {
    template: initialTemplate,
    time: null,
    message: "",
    history: [],
    selectedCells: [],
    matrixState: initialTemplate.matrix,
  },

  stateWaitingForInput: {
    actions: {},
    transitions: {
      continue: {
        target: "statePlaying",
        action({ prevState, context: { getContext } }) {
          console.log("Continue from", prevState, getContext());
        },
      },
      solution: {
        target: "stateSolution",
        action() {
          console.log("Solution");
        },
      },
      chooseTemplate: {
        target: "stateWaitingForInput",
        action({ data, context: { getContext, updateContext } }) {
          updateContext({
            template: data.template,
            matrixState: data.template.matrix,
          });
          console.log("Select template", getContext());
        },
      },
      getRandomGame: {
        target: "stateWaitingForInput",
        action({ data, context: { updateContext } }) {
          updateContext({
            template: data.template,
            matrixState: data.template.matrix,
          });
          console.log(`Random game from waiting: ${data.template.name}`);
        },
      },
      cellClickRight: {
        target: "statePlaying",
        action: cellClickRightAction,
      },
      cellClick: {
        target: "statePlaying",
        action: cellClickAction,
      },
    },
  },
  statePlaying: {
    actions: {
      onEnter({ prevState, trigger }) {
        console.log(`Enter: Playing ${prevState} by ${trigger}`);
      },
    },
    transitions: {
      getRandomGame: {
        target: "stateWaitingForInput",
        action({ data, context: { updateContext } }) {
          updateContext({
            template: data.template,
            matrixState: data.template.matrix,
          });
          console.log(`Random game from playing: ${data.template.name}`);
        },
      },
      chooseTemplate: {
        target: "stateWaitingForInput",
        action({ data, context: { updateContext } }) {
          updateContext({
            template: data.template,
            matrixState: data.template.matrix,
          });
          console.log("Select template from playing");
        },
      },
      cellClickRight: {
        target: "statePlaying",
        action: cellClickRightAction,
      },
      cellClick: {
        target: "statePlaying",
        action: cellClickAction,
      },
      win: {
        target: "stateGameOver",
        action({ context: { updateContext, getContext } }) {
          const { template, time } = getContext();

          const solvedTemplate = template.name;

          const formattedTime = new Date(time * 1000)
            .toISOString()
            .substr(14, 5);

          let history = JSON.parse(localStorage.getItem("gameHistory")) || [];

          history.push({
            solvedTemplate,
            difficulty: template.difficulty,
            time: formattedTime,
          });

          history = history.sort((a, b) => {
            const [aMin, aSec] = a.time.split(":").map(Number);
            const [bMin, bSec] = b.time.split(":").map(Number);
            return bMin * 60 + bSec - (aMin * 60 + aSec);
          });

          history = history.slice(0, 5);

          localStorage.setItem("gameHistory", JSON.stringify(history));
          updateContext({ history });

          console.log("Win");
        },
      },
      reset: {
        target: "stateWaitingForInput",
        action({ context: { updateContext } }) {
          updateContext({ selectedCells: [] });
          console.log(`Reset`);
        },
      },
      saveGame: {
        target: "statePlaying",
        action({ data, context: { getContext, updateContext } }) {
          updateContext({
            context: {
              history: [
                {
                  time: data.time,
                  selectedCells: data.selectedCells,
                  template: data.template,
                  matrixState: data.matrix,
                },
              ],
            },
          });
          console.log("Save", getContext());
        },
      },
      continue: {
        target: "stateWaitingForInput",
        action({ context: { updateContext } }) {
          updateContext(getDataFromLS());
        },
      },
      solution: {
        target: "stateSolution",
        action({ context: { updateContext } }) {
          updateContext({ selectedCells: [] });
          console.log("Solution");
        },
      },
    },
  },
  stateSolution: {
    actions: {},
    transitions: {
      reset: {
        target: "stateWaitingForInput",
        action({ context: { updateContext } }) {
          updateContext({ selectedCells: [] });
          console.log(`Reset`);
        },
      },
    },
    chooseTemplate: {
      target: "stateWaitingForInput",
      action({ data, context: { getContext, updateContext } }) {
        updateContext({
          template: data.template,
          matrixState: data.template.matrix,
        });
        console.log("Select template", getContext());
      },
    },
  },

  stateGameOver: {
    actions: {
      onEnter() {
        console.log(`Enter: Game over`);
      },
    },
    transitions: {
      chooseTemplate: {
        target: "stateWaitingForInput",
        action({ data, context: { updateContext } }) {
          updateContext({
            template: data.template,
            matrixState: data.template.matrix,
          });
          console.log("Select template from init");
        },
      },
      reset: {
        target: "stateWaitingForInput",
        action() {
          console.log(`Reset`);
        },
      },

      getRandomGame: {
        target: "stateWaitingForInput",
        action({ data, context: { updateContext } }) {
          updateContext({
            template: data.template,
            matrixState: data.template.matrix,
          });
          console.log(`random game: ${data.template.name}`);
        },
      },
    },
  },
});

export { stateMachine };
